import path from 'node:path';
import { TanStackRouterVite } from '@tanstack/router-plugin/vite';
import react from '@vitejs/plugin-react';
import { defineConfig } from 'vite';

export default defineConfig({
  appType: 'spa',
  // src/main.tsx uses a top-level `await` to halt SPA boot during the
  // PAT-in-URL handoff redirect. Vite's default target (es2020 + safari14)
  // doesn't allow top-level await, so prod builds fail in esbuild's
  // transpile step. Bump to esnext — every browser we ship to (Chromium ≥89,
  // Safari ≥15, Firefox ≥90) supports top-level await natively.
  build: {
    target: 'esnext',
    // Workspace packages resolve to their real paths outside node_modules.
    // Include their compiled output so Rollup transforms CommonJS exports
    // before those modules reach a browser chunk.
    commonjsOptions: {
      include: [/node_modules/, /packages[\\/][^\\/]+[\\/]dist/],
    },
  },
  plugins: [
    TanStackRouterVite({
      routesDirectory: './src/app',
      generatedRouteTree: './src/routeTree.gen.ts',
      // Split each route's component into its own lazy chunk so the initial
      // bundle only carries the router shell + the landed route, not all 37
      // route trees. One flag instead of hand-maintaining .lazy.tsx files.
      autoCodeSplitting: true,
    }),
    react(),
  ],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, './src'),
      // @lobu/core ships CJS dist (`module: CommonJS`). Vite dev would otherwise
      // serve dist/*.js raw over ESM (`exports is not defined`). Point the
      // browser at source — same as the package's `"bun"` export condition.
      // ONLY browser-safe subpaths (errors, reserved). Never alias the package
      // root: the barrel re-exports logger/otel/sentry and would crash the SPA
      // with `process is not defined`.
      '@lobu/core/errors': path.resolve(__dirname, '../core/src/errors.ts'),
      '@lobu/core/reserved': path.resolve(__dirname, '../core/src/reserved.ts'),
    },
  },
  optimizeDeps: {
    // If anything else hits @lobu/core CJS dist, force prebundle interop.
    include: ['@lobu/core/errors', '@lobu/core/reserved', '@shadcn/react/message-scroller'],
  },
  server: {
    allowedHosts: true,
    hmr: process.env.VITE_HMR_HOST
      ? {
          host: process.env.VITE_HMR_HOST,
          clientPort: Number(process.env.VITE_HMR_CLIENT_PORT || 8443),
          protocol: process.env.VITE_HMR_PROTOCOL || 'wss',
        }
      : undefined,
  },
});

