import { parseEntityPath } from '../url';

const DEFAULT_API_URL =
  typeof window !== 'undefined' ? window.location.origin : 'http://localhost:8787';
export const API_URL = import.meta.env.VITE_API_URL || DEFAULT_API_URL;

// In the extension's embedded iframe the session cookie isn't delivered, so
// authenticate same-origin API calls with the Bearer session token instead.
// Gated to the API origin so the token never leaks to a third-party URL; a no-op
// for normal web sessions (no token → cookie auth, unchanged).
function isApiOrigin(input: RequestInfo | URL): boolean {
  try {
    const href =
      typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
    const base = typeof window !== 'undefined' ? window.location.href : API_URL;
    return new URL(href, base).origin === new URL(API_URL).origin;
  } catch {
    return false;
  }
}

