383	function connectorNeedsSetup(
384	  connector: ConnectorDefinitionItem,
385	  group: ConnectionConnectorGroup | undefined,
386	  methods: ReturnType<typeof getAuthMethods>,
387	  profileCounts: Record<
388	    "env" | "oauth_app" | "oauth_account" | "browser_session",
389	    number
390	  >
391	): boolean {
392	  // "Needs setup" means an INSTALLED connector is missing a required binding
393	  // (credentials / OAuth app / app install / device) — NOT merely "not added".
394	  // Uninstalled catalog entries no longer render in this list, so being
395	  // uninstalled is not a setup state here.
396	  if (
397	    methods.some((m) => m.type === "oauth") &&
398	    profileCounts.oauth_app === 0
399	  ) {
400	    return true;
401	  }
402	  if (methods.some((m) => m.type === "env_keys") && profileCounts.env === 0) {
403	    return true;
404	  }
405	  if (methods.some((m) => m.type === "app_installation") && !group) {
406	    return true;
407	  }
408	  // Device-bound connector (declares a required_capability) with no connection
409	  // yet: its runtime binding is unsatisfied. `!group` mirrors the app_install
410	  // branch above — resolveDeviceBinding guarantees no connection exists for
411	  // these without a valid device, so a group implies the binding is done.
412	  if (connector.required_capability && !group) {
413	    return true;
414	  }
415	  return false;
416	}
