import type { ReactNode } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

/**
 * Page chrome shared by the connector-detail and connection-detail routes:
 * a sticky header, the tab bar, a left rail, and the content pane. Both routes
 * grew the same shape independently and drifted — three different width rules
 * (max-w-3xl / unconstrained / max-w-6xl) and two header spacings across two
 * files. Centralising the chrome makes that drift impossible; the routes still
 * own their own tabs, rails and content.
 *
 * Every mode renders the tab bar, including the feed-detail and add-feed views
 * one level down. Omitting it there used to slide the whole page up by the
 * bar's height on entry and back down on exit.
 */
export function ConnectorPageShell({
	header,
	tabs,
	value,
	onValueChange,
	rail,
	children,
}: {
	/** Breadcrumb + title block. Always sticky. */
	header: ReactNode;
	/** Tab triggers, in order. */
	tabs: { value: string; label: string; disabled?: boolean }[];
	/**
	 * Active tab. Always controlled by the caller from the URL, so it survives
	 * navigation between the connector and its connections instead of silently
	 * resetting.
	 */
	value: string;
	onValueChange: (value: string) => void;
	/** Left rail — connections or feeds. */
	rail?: ReactNode;
	children: ReactNode;
}) {
	// One sticky treatment for both routes — previously space-y-3 here and
	// space-y-2 on the connection page, for no reason anyone could name.
	const sticky =
		"sticky top-11 z-10 -mx-4 bg-background px-4 pt-1 pb-0 lg:-mx-6 lg:px-6";
	// The CONTENT column is what the eye tracks, so it is centred on every page
	// in this section — the same max-w-3xl column, at the same x, as the
	// Connectors list and the rest of the app. Navigating into a connector never
	// moves the text you are reading.
	//
	// Centring rail+content as one group instead is geometrically balanced but
	// reads wrong: the rail is sparse and the content is dense, so the eye
	// centres on the content, which that arrangement pushed ~120px right of the
	// top nav. The rail therefore lives in the left margin next to the column
	// rather than displacing it.
	const COLUMN = "relative mx-auto w-full max-w-3xl";
	// Sits in the margin at lg+; below lg there is no margin to occupy, so it
	// returns to normal flow and stacks above the content.
	const RAIL_SLOT =
		"mb-6 lg:absolute lg:right-full lg:top-0 lg:mb-0 lg:mr-6 lg:w-52 xl:w-56";

	const body = (
		<div className={cn("mt-6", COLUMN)}>
			{rail ? <div className={RAIL_SLOT}>{rail}</div> : null}
			{/* Never a full-height flex column: that lets an empty state's
			    justify-center float mid-page with dead space below it. */}
			<div className="min-w-0 space-y-6">{children}</div>
		</div>
	);

	return (
		<div className="flex flex-1 flex-col">
			<Tabs
				value={value}
				onValueChange={onValueChange}
				className="flex min-h-0 flex-1 flex-col"
			>
				<div className={sticky}>
					<div className={cn("space-y-3", COLUMN)}>
						{header}
						<TabsList>
							{tabs.map((tab) => (
								<TabsTrigger
									key={tab.value}
									value={tab.value}
									disabled={tab.disabled}
								>
									{tab.label}
								</TabsTrigger>
							))}
						</TabsList>
					</div>
				</div>
				{body}
			</Tabs>
		</div>
	);
}

