2	//
3	// The extension embeds owletto-web as a CROSS-SITE iframe (top-level origin
4	// chrome-extension://…). A session cookie is unreliable inside that partition,
5	// so the gateway's /api/extension-bootstrap page exchanges the extension's
6	// deep-link token for a Better Auth session token and stashes it in
7	// sessionStorage under this key before handing control to the SPA. The SPA then
8	// sends it as `Authorization: Bearer` on every API + auth call (the cloud auth
9	// bridge passes request headers to Better Auth, and the bearer() plugin honours
10	// the header). Empty for normal first-party web sessions, which keep using the
11	// session cookie unchanged.
12	const STORAGE_KEY = 'owletto.session_token';
13	
14	let cached: string | null | undefined;
15	
16	/**
17	 * The embedded Bearer session token, or '' when not running embedded (normal
18	 * web). Read once and memoized — the bootstrap writes it before the SPA boots.
19	 * '' is the documented "no token" sentinel for better-auth's fetchOptions.auth.
20	 */
21	export function getEmbeddedSessionToken(): string {
22	  if (cached === undefined) {
23	    try {
24	      cached =
25	        typeof window !== 'undefined' ? window.sessionStorage.getItem(STORAGE_KEY) : null;
26	    } catch {
27	      cached = null;
28	    }
29	  }
30	  return cached ?? '';
31	}
32	
33	/**
34	 * True when the SPA is running inside the extension's cross-site side-panel
35	 * iframe — independent of whether a Bearer token is present.
36	 *
37	 * Why this exists separately from the token: when the extension's deep-link
38	 * token is expired/absent, the bootstrap can't mint a session token, so
39	 * sessionStorage stays empty. If we keyed "embedded?" on the token alone, that
40	 * case would fall back to the normal-web auth path (Better Auth's useSession),
41	 * which NEVER settles in this storage partition — a permanent loading spinner.
42	 * Detecting the iframe by its chrome-extension:// ancestor keeps us on the
43	 * settling Bearer/cookie query path even token-less, so the panel resolves to
44	 * either authenticated (cookie still valid) or a clean signed-out screen instead
45	 * of hanging.
46	 */
47	export function isEmbeddedContext(): boolean {
48	  if (typeof window === 'undefined') return false;
49	  // A stashed token means the bootstrap ran — unambiguously embedded.
50	  if (getEmbeddedSessionToken()) return true;
51	  // Token-less: detect the iframe by its extension ancestor. ancestorOrigins is
52	  // Chromium-only (the extension is Chrome-only) and lists each frame ancestor's
53	  // origin; the side panel's is chrome-extension://<id>.
54	  try {
55	    const ancestors = window.location.ancestorOrigins;
56	    if (ancestors) {
57	      for (let i = 0; i < ancestors.length; i++) {
58	        if (ancestors[i].startsWith('chrome-extension://')) return true;
59	      }
60	    }
61	  } catch {
62	    // ancestorOrigins unavailable — treat as non-embedded.
63	  }
64	  return false;
65	}
66	
67	/**
68	 * Drop the embedded token on sign-out so the panel can't keep authenticating as
69	 * the signed-out user until the iframe remounts. Clears both the memo and the
70	 * stored value.
71	 */
72	export function clearEmbeddedSessionToken(): void {
73	  cached = '';
74	  try {
75	    if (typeof window !== 'undefined') window.sessionStorage.removeItem(STORAGE_KEY);
76	  } catch {
77	    // ignore — sessionStorage may be unavailable
78	  }
79	}
