/**
 * Devices tab: your paired Mac / Chrome extension / CLI as runtimes. Devices are
 * user-owned and private ("Yours") — they follow you across workspaces — so they
 * carry that badge even on this org-scoped page.
 */
function DevicesTab() {
  const { owner } = Route.useParams();
  const { data: devices = [], isLoading } = useDevices();
  const [adding, setAdding] = useState(false);

  return (
    <InfraTabScaffold
      lede="Your Mac, browser extension, or CLI — they run device-bound connectors and follow you across every workspace."
      addLabel="Add a device"
      adding={adding}
      onStartAdd={() => setAdding(true)}
      isLoading={isLoading}
      loadingSkeleton={<InfraListSkeleton />}
      isEmpty={devices.length === 0}
      emptyIcon={MonitorSmartphone}
      emptyTitle="No devices connected"
      emptyDescription="Pair a Mac, browser extension, or CLI to run device-bound connectors."
      form={<DeviceConnect owner={owner} onClose={() => setAdding(false)} />}
    >
      {devices.map((device, idx) => (
        <Link
          key={device.id}
          to="/$owner/infrastructure/devices/$deviceId"
          params={{ owner, deviceId: device.id }}
