import type { LucideIcon } from "lucide-react";
import { Plus } from "lucide-react";
import type { ReactNode } from "react";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

/** Shared list and add-form layout for the Connect infrastructure tabs. */
export function InfraTabScaffold({
	lede,
	addLabel,
	adding,
	onStartAdd,
	isLoading,
	loadingSkeleton,
	isEmpty,
	emptyIcon,
	emptyTitle,
	emptyDescription,
	banner,
	form,
	children,
}: {
	lede: string;
	addLabel: string;
	adding: boolean;
	onStartAdd: () => void;
	isLoading: boolean;
	loadingSkeleton: ReactNode;
	isEmpty: boolean;
	emptyIcon: LucideIcon;
	emptyTitle: string;
	emptyDescription: string;
	banner?: ReactNode;
	form?: ReactNode;
	children?: ReactNode;
}) {
	// Header Add only when the list already has items. An empty tab already
	// carries the primary CTA in TabEmptyState — doubling it in the lede row
	// is noise (Models/Sandboxes/Devices all share this scaffold).
	const showHeaderAdd = !adding && !isLoading && !isEmpty;

	return (
		<div className="max-w-3xl space-y-4">
			{banner}

			<div className="flex flex-wrap items-center justify-between gap-3">
				<p className="text-sm text-muted-foreground">{lede}</p>
				{showHeaderAdd ? (
					<Button
						variant="outline"
						size="sm"
						className="h-8 shrink-0 text-xs"
						onClick={onStartAdd}
					>
						<Plus className="mr-1.5 h-3.5 w-3.5" />
						{addLabel}
					</Button>
				) : null}
			</div>

			{isLoading ? (
				loadingSkeleton
			) : isEmpty ? (
				<TabEmptyState
					icon={emptyIcon}
					title={emptyTitle}
					description={emptyDescription}
					actionLabel={adding ? undefined : addLabel}
					onAction={adding ? undefined : onStartAdd}
				/>
			) : (
				<div className="overflow-hidden rounded-lg border">{children}</div>
			)}

			{adding ? form : null}
		</div>
	);
}

/** Shared loading skeleton for the infra list — two bordered rows. */
export function InfraListSkeleton({ rows = 2 }: { rows?: number }) {
	return (
		<div className="overflow-hidden rounded-lg border">
			{Array.from({ length: rows }).map((_, i) => (
				<div
					// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
					key={i}
					className={`flex items-center gap-3 px-3 py-3 ${
						i === rows - 1 ? "" : "border-b"
					}`}
				>
					<Skeleton className="h-4 w-4 shrink-0 rounded-sm" />
					<Skeleton className="h-4 max-w-[12rem] flex-1" />
				</div>
			))}
		</div>
	);
}

